import { Input, Message, Time } from "./types";

type Output = {
  text: string;
};

export const inputs = ["/smMissionID", "/smState"];
export const output = "/missionData";

let lastReceiveTime: Time = { sec: 0, nsec: 0 };

const mission: {
  id?: Message<"std_msgs/UInt32">;
  state?: Message<"std_msgs/String">;
} = {};

export default function script(
  event: Input<"/smMissionID"> | Input<"/smState">,
): Output | undefined {
  const { receiveTime, topic, message } = event;

  let inSync = true;

  if (
    receiveTime.sec !== lastReceiveTime.sec ||
    receiveTime.nsec !== lastReceiveTime.nsec
  ) {
    lastReceiveTime = receiveTime;
    inSync = false;
  }

  if (topic === "/smMissionID") {
    mission.id = message;
  } else if (topic === "/smState") {
    mission.state = message;
  }

  if (!inSync) {
    return undefined;
  }

  return {
    text:
      "Mission ID: " +
      (mission.id?.data ?? "unknown") +
      "\n" +
      (mission.state?.data ?? "unknown"),
  };
}

