import { Input, Message } from "./types.ts";

type Output = {
  data: string;
};

export const inputs = ["/diagnostics"];

export const output = "/diagnostics/diagnostic_error";

export default function script(event: Input<"/diagnostics">): Output {
  const diagArray = (event.message as any).status;

  if (diagArray && Array.isArray(diagArray)) {
    const errors = new Set<string>();

    for (const status of diagArray) {
      if (status.level === 2) {
        errors.add(`${status.name}: ${status.message}`);
      }
    }

    if (errors.size > 0) {
      return { data: Array.from(errors).join("\n") };
    }
  }

  return { data: "Nincs hiba" };
}

