import { Message } from "./types";

type GPSOutput = {
  latitude: number;
  longitude: number;
  altitude: number;
  status: { status: number; service: number };
  position_covariance: number[];
  position_covariance_type: number;
};

// Generikus stringként adjuk meg, így a TypeScript nem ellenőrzi a fix létezését
export const inputs: string[] = [
  "/home/csanda/Downloads/mobilis-bing-nyomvonal.txt",
];
export const output = "/converted_gps_path";

let isProcessed = false;

// Az event típusát any-re állítjuk, hogy ne akadjon fent a keyof constraint-en
export default function script(event: any, log: any): GPSOutput | undefined {
  if (isProcessed) return undefined;

  // Biztonsági ellenőrzés, hogy valóban a mi fájlunk jött-e be
  if (
    event.topic !==
    "/home/csanda/Downloads/AUC_-_Bing_-_Mobilis_-_Center_kml_txt"
  ) {
    return undefined;
  }

  const csvData = event.message?.data;
  if (!csvData) return undefined;

  const lines = csvData.split("\n");

  // Győr / Mobilis Center koordinátákhoz az UTM 33N zóna a tökéletes
  const zone = 33;
  const northernHemisphere = true;

  for (let i = 1; i < lines.length; i++) {
    const columns = lines[i].split(",");
    if (columns.length < 2) continue;

    const utmX = parseFloat(columns[0]);
    const utmY = parseFloat(columns[1]);
    const altitude = parseFloat(columns[2]) || 0;

    if (!isNaN(utmX) && !isNaN(utmY)) {
      const { lat, lon } = utmToLatLon(utmX, utmY, zone, northernHemisphere);

      log.publish("/converted_gps_path", {
        latitude: lat,
        longitude: lon,
        altitude: altitude,
        status: { status: 0, service: 1 },
        position_covariance: [0, 0, 0, 0, 0, 0, 0, 0, 0],
        position_covariance_type: 0,
      });
    }
  }

  isProcessed = true;
  return undefined;
}

// UTM -> WGS84 Konverter
function utmToLatLon(
  x: number,
  y: number,
  zone: number,
  northernHemisphere: boolean,
) {
  const sa = 6378137.0;
  const sb = 6356752.314245;
  const e2 = Math.sqrt(sa * sa - sb * sb) / sb;
  const e2cuadrada = e2 * e2;
  const c = (sa * sa) / sb;

  const xang = x - 500000.0;
  const yang = northernHemisphere ? y : y - 10000000.0;

  const v =
    (c /
      Math.sqrt(
        1 +
          e2cuadrada *
            Math.cos(yang / (6366197.724 * 0.9996)) *
            Math.cos(yang / (6366197.724 * 0.9996)),
      )) *
    0.9996;
  const a = xang / v;
  const a1 = Math.sin(2 * (yang / (6366197.724 * 0.9996)));
  const a2 =
    a1 *
    Math.cos(yang / (6366197.724 * 0.9996)) *
    Math.cos(yang / (6366197.724 * 0.9996));
  const j2 = yang / (6366197.724 * 0.9996) + a1 / 2;
  const j4 = (3 * j2 + a2) / 4;
  const j6 =
    (5 * j4 +
      a2 *
        Math.cos(yang / (6366197.724 * 0.9996)) *
        Math.cos(yang / (6366197.724 * 0.9996))) /
    3;
  const alfa = (3 / 4) * e2cuadrada;
  const beta = (15 / 32) * (e2cuadrada * e2cuadrada);
  const gama = (35 / 27) * (e2cuadrada * e2cuadrada * e2cuadrada);
  const bm =
    0.9996 *
    c *
    (yang / (6366197.724 * 0.9996) - alfa * j2 + beta * j4 - gama * j6);
  const b = (yang - bm) / v;
  const eplus =
    ((e2cuadrada * (a * a)) / 2) *
    Math.cos(yang / (6366197.724 * 0.9996)) *
    Math.cos(yang / (6366197.724 * 0.9996));
  const ith = a * (1 - eplus / 3);
  const lat =
    yang / (6366197.724 * 0.9996) +
    (180 / Math.PI) * (b * (1 - eplus) * (1 - (e2cuadrada * (a * a)) / 2));
  const lon =
    zone * 6 -
    183 +
    ((180 / Math.PI) * ith) / Math.cos(yang / (6366197.724 * 0.9996));

  const latGrad = lat - (lat - Math.floor(lat));
  const latMin = (lat - latGrad) * 60;
  const latSec = (latMin - Math.floor(latMin)) * 60;
  const finalLat = latGrad + Math.floor(latMin) / 60 + latSec / 3600;

  const lonGrad = lon - (lon - Math.floor(lon));
  const lonMin = (lon - lonGrad) * 60;
  const lonSec = (lonMin - Math.floor(lonMin)) * 60;
  const finalLon = lonGrad + Math.floor(lonMin) / 60 + lonSec / 3600;

  return { lat: finalLat, lon: finalLon };
}

