type Output = {
  uncertainty: string;
};

export const inputs = ["/vectornav/raw/gps"];
export const output = "/gps_uncertainty";

export default function script(event: {
  message: Record<string, any>;
  topic: string;
}): Output {
  const msg = event.message;
  const fallback: Output = {
    uncertainty: "No data",
  };

  if (!msg) return fallback;

  const posu = msg["posu"];
  if (!posu) return fallback;

  const x = posu["x"];
  const y = posu["y"];

  if (typeof x === "number" && typeof y === "number") {
    const average = (x + y) / 2;

    return {
      uncertainty: average.toFixed(2) + " m",
    };
  }

  return fallback;
}
